#include "checks_syntax.h"
int check_unmatched_brace(SourceFile*f,Project*p,Issue*out){int cnt=0;int brace=0;int paren=0;int brack=0;int comment=0;char*content=f->content;if(!content)return 0;for(long long i=0;content[i];i++){char c=content[i];if(c=='/'&&content[i+1]=='*'){comment=1;i++;continue;}if(c=='*'&&content[i+1]=='/'&&comment){comment=0;i++;continue;}if(comment)continue;if(c=='/'){if(content[i+1]=='/'){while(content[i]&&content[i]!='\n')i++;continue;}}if(c=='{')brace++;if(c=='}'){brace--;if(brace<0){cnt++;if(cnt==1&&out){out->loc.line=util_get_line_number(content,content+i);out->loc.col=util_get_column(content,content+i);snprintf(out->loc.file,sizeof(out->loc.file),"%s",f->path);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1001;snprintf(out->msg,sizeof(out->msg),"Unmatched closing brace '}'");snprintf(out->suggestion,sizeof(out->suggestion),"Check for missing opening brace");brace=0;}}}
if(c=='(')paren++;if(c==')'){paren--;if(paren<0){cnt++;if(cnt==1&&out){out->loc.line=util_get_line_number(content,content+i);}}}
if(c=='[')brack++;if(c==']'){brack--;if(brack<0){cnt++;}}
if(brace>0){cnt++;if(cnt==1&&out){out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1001;snprintf(out->msg,sizeof(out->msg),"Unmatched opening brace(s): %d extra",brace);}}
if(paren>0){cnt++;if(cnt==1&&out){out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1001;snprintf(out->msg,sizeof(out->msg),"Unmatched parenthesis: %d extra",paren);}}
if(brack>0){cnt++;if(cnt==1&&out){out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1001;snprintf(out->msg,sizeof(out->msg),"Unmatched bracket(s): %d extra",brack);}}
if(comment){cnt++;if(cnt==1&&out){out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1001;snprintf(out->msg,sizeof(out->msg),"Unclosed comment block");}}
return cnt>0?1:cnt;}}
int check_missing_semicolon(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){Token*t=&f->tokens[i];if(t->type==TK_RPAREN||t->type==TK_RBRACE||t->type==TK_RBRACK||t->type==TK_ID||t->type==TK_NUMBER){Token*n=&f->tokens[i+1];if(n->type==TK_RBRACE||n->type==TK_BLOCK_CLOSE)continue;if(n->type==TK_EOF)break;if(n->type==TK_SEMI)continue;if(n->type==TK_ELSE||n->type==TK_WHILE||n->type==TK_RPAREN||n->type==TK_RBRACK||n->type==TK_RBRACE||n->type==TK_BLOCK_CLOSE)continue;if(n->type==TK_LBRACE||n->type==TK_BLOCK_OPEN)continue;if(n->type==TK_LPAREN)continue;if(t->type==TK_ID){
int is_type=lexer_is_type_keyword(t->text);if(!is_type){int maybe_missing=0;if(n->type==TK_ID||n->type==TK_LBRACE||n->type==TK_BLOCK_OPEN||n->type==TK_IF||n->type==TK_WHILE||n->type==TK_FOR||n->type==TK_SWITCH||n->type==TK_RETURN||n->type==TK_BREAK||n->type==TK_CONTINUE||n->type==TK_GOTO){maybe_missing=1;}if(maybe_missing){cnt++;if(cnt==1&&out){out->loc.line=t->line;out->loc.col=t->col;out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1002;snprintf(out->msg,sizeof(out->msg),"Possible missing semicolon after '%s'",t->text);}}}}}}return cnt;}
int check_missing_return(SourceFile*f,Project*p,Issue*out){int cnt=0;int func_start=-1;char func_name[256]="";for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(i+1)<f->ntokens&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){snprintf(func_name,sizeof(func_name),"%s",f->tokens[i].text);func_start=j;int has_return=0;int brace_depth=1;int k=j+1;while(k<f->ntokens&&brace_depth>0){if(f->tokens[k].type==TK_BLOCK_OPEN||f->tokens[k].type==TK_LBRACE)brace_depth++;if(f->tokens[k].type==TK_BLOCK_CLOSE||f->tokens[k].type==TK_RBRACE){brace_depth--;if(brace_depth==0)break;}if(f->tokens[k].type==TK_RETURN)has_return=1;k++;}if(!has_return){int is_void_func=0;for(int m=i-1;m>=0&&m>i-10;m--){if(f->tokens[m].type==TK_VOID){is_void_func=1;break;}}if(!is_void_func){cnt++;if(cnt==1&&out){LOC_TOK(out,f,func_start);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1003;snprintf(out->msg,sizeof(out->msg),"Non-void function '%s' may be missing return statement",func_name);snprintf(out->suggestion,sizeof(out->suggestion),"Add a return statement at the end of the function");}}}}}}return cnt;}
int check_unclosed_comment(SourceFile*f,Project*p,Issue*out){int cnt=0;char*content=f->content;if(!content)return 0;int in_comment=0;long long comment_start=0;for(long long i=0;content[i];i++){if(!in_comment&&content[i]=='/'&&content[i+1]=='*'){in_comment=1;comment_start=i;i++;}else if(in_comment&&content[i]=='*'&&content[i+1]=='/'){in_comment=0;i++;}}if(in_comment){cnt++;if(cnt==1&&out){out->loc.line=util_get_line_number(content,content+comment_start);out->loc.col=util_get_column(content,content+comment_start);snprintf(out->loc.file,sizeof(out->loc.file),"%s",f->path);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1004;snprintf(out->msg,sizeof(out->msg),"Unclosed multi-line comment");snprintf(out->suggestion,sizeof(out->suggestion),"Add '*/' to close the comment");}}return cnt;}
int check_duplicate_include(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->nincludes;i++){for(int j=i+1;j<f->nincludes;j++){if(strcmp(f->includes[i],f->includes[j])==0){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1005;snprintf(out->msg,sizeof(out->msg),"Duplicate include: %s",f->includes[i]);}}}}return cnt;}
int check_missing_include_guard(SourceFile*f,Project*p,Issue*out){int cnt=0;if(f->lang!=LANG_HEADER)return 0;if(f->include_guard[0]==0){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1006;snprintf(out->msg,sizeof(out->msg),"Header file missing include guard");snprintf(out->suggestion,sizeof(out->suggestion),"Add #ifndef/#define/#endif guard at top/bottom of header");}}return cnt;}
int check_empty_translation(SourceFile*f,Project*p,Issue*out){int cnt=0;if(f->ntokens<=2&&f->size>0){cnt++;if(cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_SYNTAX;out->code=1007;snprintf(out->msg,sizeof(out->msg),"Empty or nearly empty translation unit");}}return cnt;}
int check_switch_fallthrough(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_CASE||f->tokens[i].type==TK_DEFAULT){int j=i+1;while(j<f->ntokens&&f->tokens[j].type!=TK_CASE&&f->tokens[j].type!=TK_DEFAULT&&f->tokens[j].type!=TK_RBRACE&&f->tokens[j].type!=TK_BLOCK_CLOSE){if(f->tokens[j].type==TK_BREAK||f->tokens[j].type==TK_RETURN)break;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_CASE||f->tokens[j].type==TK_DEFAULT)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1008;snprintf(out->msg,sizeof(out->msg),"Switch case may fall through without break");snprintf(out->suggestion,sizeof(out->suggestion),"Add break statement or /* fallthrough */ comment");}}}}return cnt;}
int check_duplicate_case(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_CASE&&f->tokens[i+1].type==TK_NUMBER){long long val=f->tokens[i+1].val;for(int j=i+2;j<f->ntokens-2;j++){if(f->tokens[j].type==TK_CASE&&f->tokens[j+1].type==TK_NUMBER&&f->tokens[j+1].val==val){cnt++;if(cnt==1&&out){LOC_TOK(out,f,j);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1009;snprintf(out->msg,sizeof(out->msg),"Duplicate case value: %lld",val);}}}}}return cnt;}
int check_unreachable_code(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_RETURN&&f->tokens[i+1].type==TK_SEMI){for(int j=i+2;j<f->ntokens-1&&j<i+20;j++){if(f->tokens[j].type==TK_RBRACE||f->tokens[j].type==TK_BLOCK_CLOSE)break;if(f->tokens[j].type==TK_RETURN||f->tokens[j].type==TK_BREAK||f->tokens[j].type==TK_CONTINUE||f->tokens[j].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,j);out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1010;snprintf(out->msg,sizeof(out->msg),"Unreachable code after return statement");snprintf(out->suggestion,sizeof(out->suggestion),"Remove unreachable code or restructure");}break;}}}}return cnt;}
int check_missing_void_param(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN&&f->tokens[i+2].type==TK_RPAREN){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_SYNTAX;out->code=1011;snprintf(out->msg,sizeof(out->msg),"Function declaration without 'void' parameter: %s()",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Use %s(void) for clarity",f->tokens[i].text);}}}return cnt;}
int check_empty_if_body(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_IF&&f->tokens[i+1].type==TK_LPAREN){int depth=1;int j=i+2;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&f->tokens[j].type==TK_SEMI){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1012;snprintf(out->msg,sizeof(out->msg),"Empty if body");snprintf(out->suggestion,sizeof(out->suggestion),"Add braces or remove the if statement");}}}}return cnt;}
int check_empty_while_body(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_WHILE&&f->tokens[i+1].type==TK_LPAREN){int depth=1;int j=i+2;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&f->tokens[j].type==TK_SEMI){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1013;snprintf(out->msg,sizeof(out->msg),"Empty while body");}}}}return cnt;}
int check_empty_for_body(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_FOR&&f->tokens[i+1].type==TK_LPAREN){int depth=1;int j=i+2;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&f->tokens[j].type==TK_SEMI){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SYNTAX;out->code=1014;snprintf(out->msg,sizeof(out->msg),"Empty for loop body");}}}}return cnt;}
int check_label_duplicate(SourceFile*f,Project*p,Issue*out){int cnt=0;typedef struct{char name[256];int line;}Label;Label*labels=NULL;int nlabels=0;int cap=0;for(int i=0;i<f->ntokens-1;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_COLON){int dup=0;for(int j=0;j<nlabels;j++){if(strcmp(labels[j].name,f->tokens[i].text)==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1015;snprintf(out->msg,sizeof(out->msg),"Duplicate label '%s'",f->tokens[i].text);}dup=1;break;}}if(!dup){if(nlabels>=cap){cap=cap?cap*2:16;labels=realloc(labels,cap*sizeof(Label));}snprintf(labels[nlabels].name,sizeof(labels[nlabels].name),"%s",f->tokens[i].text);labels[nlabels].line=f->tokens[i].line;nlabels++;}}}if(labels)free(labels);return cnt;}
int check_break_outside_loop(SourceFile*f,Project*p,Issue*out){int cnt=0;int loop_depth=0;int switch_depth=0;int i; for(i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_WHILE||f->tokens[i].type==TK_FOR||f->tokens[i].type==TK_DO)loop_depth++;if(f->tokens[i].type==TK_SWITCH)switch_depth++;if(f->tokens[i].type==TK_RBRACE||f->tokens[i].type==TK_BLOCK_CLOSE){if(switch_depth>0){Token prev=f->tokens[i-1];if(prev.type!=TK_CASE&&prev.type!=TK_DEFAULT)switch_depth--;}else if(loop_depth>0)loop_depth--;}if(f->tokens[i].type==TK_BREAK&&loop_depth==0&&switch_depth==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1016;snprintf(out->msg,sizeof(out->msg),"break outside loop or switch");}}}return cnt;}
int check_continue_outside_loop(SourceFile*f,Project*p,Issue*out){int cnt=0;int loop_depth=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_WHILE||f->tokens[i].type==TK_FOR||f->tokens[i].type==TK_DO)loop_depth++;if(f->tokens[i].type==TK_RBRACE||f->tokens[i].type==TK_BLOCK_CLOSE&&loop_depth>0)loop_depth--;if(f->tokens[i].type==TK_CONTINUE&&loop_depth==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SYNTAX;out->code=1017;snprintf(out->msg,sizeof(out->msg),"continue outside loop");}}}return cnt;}
